 new ResizeObserver(resize).observe(canvas);window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='Space'&&!e.repeat)firePulse();if(e.code==='Enter'&&!playing)reset()});window.addEventListener('keyup',e=>keys[e.code]=false);document.getElementById('startButton').onclick=reset;document.getElementById('restart').onclick=()=>{playing=false;overlay.classList.remove('hidden');document.getElementById('modalTitle').textContent='Run reset';document.getElementById('modalCopy').textContent='Your neural link is stable. Recover all three signal fragments, evade the sentinels, and reach the extraction gate.';document.getElementById('startButton').textContent='BEGIN RUN  →'};
